    const embed = new MessageEmbed()
      .setColor('#ff0000')
      .setTitle('Error')
      .setDescription('An error occurred while banning the user. Please try again later.')
      .setFooter('Discord Bot');
    await interaction.reply({ embeds: [embed] });
  }
